settings_json:
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook rm-workspace-guard",
            "if": "Bash(rm:*)",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook bg-await-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook no-slop-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook precommit-check",
            "if": "Bash(git commit:*)",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook commit-message-sanitizer",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook policy-guard",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook no-slop-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook policy-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook memory-anchors"
          }
        ]
      },
      {
        "matcher": "Read",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook preread-edit-check"
          },
          {
            "type": "command",
            "command": "playbook hook preread-size-check"
          },
          {
            "type": "command",
            "command": "playbook hook doc-read-hint",
            "timeout": 10
          }
        ]
      },
      {
        "matcher": "Read|Grep|Glob|Edit|Write|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook search-counter"
          }
        ]
      },
      {
        "matcher": "AskUserQuestion",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook auto-guard",
            "timeout": 10
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook auto-cost",
            "timeout": 10
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-init"
          },
          {
            "type": "command",
            "command": "playbook hook usage-warm",
            "timeout": 5
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook memory-anchors"
          },
          {
            "type": "command",
            "command": "playbook hook auto-model-detect"
          },
          {
            "type": "command",
            "command": "playbook hook auto-guard",
            "timeout": 10
          },
          {
            "type": "command",
            "command": "playbook hook context-hygiene",
            "timeout": 10
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook post-edit-track"
          },
          {
            "type": "command",
            "command": "playbook hook rebuild-memory-graph"
          }
        ]
      },
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook commit-message-sanitizer",
            "timeout": 60
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook precompact-warn"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-clean-exit"
          },
          {
            "type": "command",
            "command": "playbook hook memory-capture"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook session-clean-exit"
          },
          {
            "type": "command",
            "command": "playbook hook usage-warm",
            "timeout": 5
          }
        ]
      }
    ],
    "WorktreeCreate": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook worktree-create",
            "timeout": 180
          }
        ]
      }
    ],
    "WorktreeRemove": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "playbook hook worktree-remove",
            "timeout": 120
          }
        ]
      }
    ]
  },
  "statusLine": {
    "type": "command",
    "command": "playbook statusline",
    "refreshInterval": 30
  }
}

